def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # Keep uniform lines that act as dividers between regions.
    sep_rows = [r for r in sep_rows if 0 < r < h - 1]
    sep_cols = [c for c in sep_cols if 0 < c < w - 1]

    def bands(length, separators):
        result = []
        start = 0
        for pos in separators:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        if start < length:
            result.append((start, length))
        return result

    row_bands = bands(h, sep_rows)
    col_bands = bands(w, sep_cols)

    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_bands
        for c0, c1 in col_bands
        for r in range(r0, r1)
        for c in range(c0, c1)
    )
    background = counts.most_common(1)[0][0]

    output = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            markers = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if markers >= 2 else background)
        output.append(row)
    return output
